def is_plain_name(name: str) -> bool:
    """True when name is one path component: no '/', no '\\', no NUL, not '.' or '..', not absolute."""
    ex is_plain_name("a.txt") == True
    ex is_plain_name("../secret.txt") == False
    ex is_plain_name("/etc/passwd") == False
    if name == "" or name == "." or name == "..":
        return False
    if name.startswith("/") or name.startswith("\\"):
        return False
    for ch in name.chars():
        if ch == "/" or ch == "\\" or ch == "\0":
            return False
    return True

def read_note(name: str) -> str | None uses fs:
    """Text of the file notes/name, or None when name is unsafe or the file cannot be read."""
    pre is_plain_name(name)
    post out is None or is_plain_name(name)
    if not is_plain_name(name):
        return None
    with fs = fs.sub("notes"):
        return fs.read_text(name) else None

def first_readable(names: list[str]) -> str uses fs:
    """Text of the first name in names readable from the notes directory, or "" when none is readable.
    Every name is confined to notes; unsafe names are skipped."""
    post out == "" or out.byte_len() > 0
    for name in names:
        if not is_plain_name(name):
            continue
        text = read_note(name)
        if text is not None:
            return text
    return ""
